class CUConnection:
    """Provides a python facade for a CU client. Is meant to be used from python code """

    def __init__(self, host, port, username, password, cu_version=CUProvider.DEFAULT, secure=False, login_disabled=False,
                 timeout=None, use_m2m=False, alias="default", read_only=False, update_expired_password=True, log_dir="",
                 log_level="info"):
        """
        Provides connection and authorization to CU.

        .. note::
            **API used:**

            +-------------------+---------------------------------------------+
            | use_m2m           | API Endpoint                                |
            +===================+=============================================+
            | False             | POST /api/sec/v1/login                      |
            +-------------------+---------------------------------------------+
            | True              | POST /api/licensed/sec/v1/login             |
            +-------------------+---------------------------------------------+

        :param str host: IP address to proper host, f.e. `127.0.0.1`.
        :param str port: Port for connection to CU.
        :param str username: Username to authenticate to CU.
        :param str password: Password to authenticate to CU.
        :param str cu_version: (optional) Specifies version of the CU.
                               Current possibilities:
                               cuoam_19b, cuoam_21b, cuoam_22r4, cuoam_23r1,
                               cuoam_23r2, cuoam_23r3, cuoam_24r1, cuoam_24r2,
                               cuoam_24r3, cuoam_25r1, cuoam_25r2, cuoam_25r3,
                               cuoam_26r1

                               Defaults to the newest implemented release - cuoam_26r1.
        :param bool secure: (optional) If set to True, the connection will be made using HTTPS protocol, otherwise with HTTP,
                            Defaults to False.
        :param bool login_disabled: (optional) If set to True, default token will be used instead log in. Defaults to False.
        :param Union[int, str] timeout: (optional) Timeout for the operation.
        :param bool use_m2m: (optional) If set to true, M2M login(/api/licensed/sec/v1/login) will be used.
                             Otherwise, internal login(/api/sec/v1/login) is used.
                             Defaults to False.
                             Must set use_m2m -> False when login first time after deployment.
        :param str alias: (optional) Name of returned connection. If not provided, this connection becomes "default".
        :param bool read_only: (optional) If set to True, the connection will be read-only. Defaults to False.
        :param bool update_expired_password: (optional) If set to True, expired password will be updated to "Nokia@123".
                                             Otherwise the user can use keyword update_expired_password to
                                             change password on their own. Defaults to True.
        :param str log_dir: (optional) directory where log messages from the library will be saved.
                            Name of the file with logs is "cu_api_debug_{connection_name}.log"
                            When this value is not given logs will be saved in the working directory.
        :param str log_level: (optional) specifies the lowest-severity log message which should be logged to console.
                              Available levels:

                              * debug
                              * info
                              * warning
                              * error
                              * critical

                              Levels are equivalent to python logging module levels,
                              more info can be found here: https://docs.python.org/3/library/logging.html#logging-levels

                              List of available levels is in severity order where "debug" is the lowest severity level
                              and "critical" is the highest severity.
                              If log_level is "info", only INFO, WARNING, ERROR, and CRITICAL messages will be directed
                              to console and DEBUG messages will be ignored.
                              Default value is "info".
        """
        set_log_level(level=log_level)
        direct_logs_to_file(path=log_dir, alias=alias)
        log_library_version()

        self._cu = CUProvider.create_cu(host=host,
                                        port=port,
                                        username=username,
                                        password=password,
                                        cu_version=cu_version,
                                        secure=secure,
                                        login_disabled=login_disabled,
                                        timeout=timeout,
                                        use_m2m=use_m2m,
                                        alias=alias,
                                        read_only=read_only,
                                        update_expired_password=update_expired_password)

        if login_disabled:
            self._cu.token_storage.set_default_token(connection_name=self._cu.con_details.alias)

        else:
            self.login_response = self._cu.sec.login(
                username=username,
                password=password,
                timeout=timeout
            )

        self.use_m2m = use_m2m
        self.connection_name = alias

    def disconnect(self, timeout=None):
        """
        Sends logout request.

        .. note::

           **API used:**

           +-------------------+---------------------------------------------+
           | use_m2m           | API Endpoint                                |
           +===================+=============================================+
           | False             | POST /api/sec/v1/logout                     |
           +-------------------+---------------------------------------------+
           | True              | POST /api/licensed/sec/v1/logout            |
           +-------------------+---------------------------------------------+

        :param int timeout: (optional) Timeout for the operation. Defaults to None
        """
        self._cu.sec.logout(timeout=timeout)
        self._cu.sec.remove_instance(self.connection_name)

    def perform_commissioning(self, scf_file, wait_for_completion=True, should_activate=True, timeout=300):
        """
        Perform Commissioning

        By default, wait_for_completion is set to True, meaning the keyword will wait until the operation is complete.
        If wait_for_completion is set to False, it is advisable to check the operation's status using
        get_status_of_perform_commissioning to confirm successful activation.

        .. note::
            SUPPORTS M2M API ONLY, one exception is first commissioning after CU deployment when M2M interface is
            disabled. In this case INTERNAL API is used to commission.
            In order to enable M2M Interface during this first commissioning please remember to set "actCli" parameter
            to True in scf_file.

        :param str scf_file: path to plan file in XML format
        :param int timeout: (optional) Timeout for the operation, defaults to 300.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
        :param should_activate: (optional) If set to True, plan will be activated, otherwise it will be validated
                                            without activation. In order to activate the pre-activated plan user
                                            should call perform_delta_recommissioning again with should_activate=True.
                                            Defaults to True.
        :return: dict with id and status of operation, for example:
                {
                  "id": "101",
                  "status": "ongoing"
                }
        """
        return self._cu.perform_commissioning(scf_file=scf_file,wait_for_completion=wait_for_completion,
                                              should_activate=should_activate, timeout=timeout)

    def get_status_of_perform_commissioning(self, operation_id, timeout=30, should_activate=True):
        """
        Get status of perform_commissioning operation

        If should_activate parameter was set to False when executing perform_commissioning, it
        should also be given as False to properly get the status.

        .. note::
            SUPPORTS M2M API ONLY

        :param str operation_id: operation id, get from keyword perform_commissioning
        :param int timeout: (optional) Timeout for the operation, defaults to 30.
        :param bool should_activate: (optional) Should be set to False if perform_commissioning
                                                was executed without activation. Defaults to True.
        :return: dict with id and status of operation, for example:
                {
                  "id": "101",
                  "status": "ongoing"
                }
        """
        return self._cu.get_status_of_perform_commissioning(operation_id=operation_id, timeout=timeout,
                                                            should_activate=should_activate)

    def upload_plan_file(self, path_to_plan_file, wait_for_completion=False, timeout=30, **kwargs):
        """
        Adds plan to the "Planned Configuration" section of the staging area

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str path_to_plan_file: (required) Path to file, which should be uploaded,
                                      like 'C:/../../SCF_vDU_update_trs_668.xml'
        :param str plan_name: (required, only for cuoam_19b) the name given to the plan, for example:'vdu_1_plan'
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param Union[object,str] connection: (optional) Unique identifier for a certain connections or CUConnection instance returned by connect_to.
        :return: dict with upload plan operation info, for example:
        {
          "raml_parsing_errors": [
            "ramlParseError1",
            "ramlParseError2"
          ],
          "incorrect_objects_feedback": [
            {
              "errorCode": "ParameterWithoutDefinition",
              "path": "MRBTS-1/MNL-1.cmSyncCheckPerio"
            }
            {
              "errorCode": "ObjectNotAllowedToCreate",
              "path:": "MRBTS-10999/NRBTS-1/LTEENB-1"
            }
          ],
          "procedure_state": "planDownload",
          "action_id": 101,
          "links": [
            {
              "rel": "self",
              "herf": "/some/useful/links"
            }
          ],
          "status": "ongoing",
          "error_message": "error message"
        }
        """
        return self._cu.upload_plan_file(path_to_plan_file=path_to_plan_file,
                                         wait_for_completion=wait_for_completion,
                                         timeout=timeout,
                                         **kwargs)

    def get_plan_file(self, plan_id, path, timeout=30, **kwargs):
        """
        Save staged plan ("Planned Configuration" section in staging area)
        to the given local path

        Supported in `cuoam_19b`.

        :param str plan_id: ID of the plan, can be taken from upload_plan keyword
        :param str path: Local path where file should be saved, consisting of file name an .xml extension,
                         for example: "/home/ute/Desktop/vdu_plan_1.xml"
        :param Union[int,str] timeout: (optional) Timeout for the operation, defaults to 10
        :param bool include_auto_config_data: (optional) Whether auto config data should be included in the plan.
                                              Defaults to False.
        :return: str saved plan content
        """
        path_to_current_plan = self._cu.get_plan_file(plan_id=plan_id, timeout=timeout, **kwargs)
        copy_file_to_new_location(path_to_current_plan, path)
        content = read_from_file(path)
        return content

    def plan_delete(self, plan_id):
        """
        Remove plan with given ID from "Planned Configuration" section of staging area.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str plan_id: ID of the plan, can be taken from upload_plan_file keyword
        """
        self._cu.plan_delete(plan_id)

    def get_plan_info(self):
        """
        Gets a list of basic plan info.

        Supported in `cuoam_19b`.

        :return: It returns list with information about available plans.
        """
        return self._cu.get_plan_info()

    def get_staged_plans_list(self):
        """
        Get a list of staged plan info

        Supported in `cuoam_21b`.

        :return: It returns list of PlanInfoResponse with staged plan info
        """
        return self._cu.get_staged_plans_list()

    def get_current_plan_file(self, path, include_runtime_data=False, timeout=120, **kwargs):
        """
        Downloads current plan file.

        .. note::
            SUPPORTS INTERNAL AND M2M API

        :param str path: Path to save plan file.
        :param bool include_runtime_data: (optional) Whether runtime date included in upload plan
        :param Union[int,str] timeout: (optional) Timeout for the operation. Set to 120 seconds by default.
        :param bool include_auto_config_data: (optional) Whether auto config data should be included in the plan.
                                              Defaults to True.
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) m2m feature activation flag.
                             If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults set to True.
        :return: content of the current plan.
        """
        return self._cu.get_current_plan_file(path, include_runtime_data, timeout, **kwargs)

    def get_current_plan_tree_diff(self):
        """
        Get plan tree with mo lites of current plan

        :return: It returns dict containing information about plan revision and  created, updated and removed
                 MoLite objects
        """
        return self._cu.get_current_plan_tree_diff()

    def search_parameters_of_current_plan(self, parameter_name, **kwargs):
        """
        Query parameter data of current plan.

        :param str parameter_name: Filter by text by any field of the parameter name
        :param int page_number: (optional) Active page number
        :param int items_per_page: (optional) The number of items per page
        :param str sort_order: (optional) Sorting order
        :param str sorted_by: (optional) Parameter search results sorting criteria

        :return: It returns dict containing search parameters response
            Example:
              {"total": 0,
              "items": [
                {
                  "moUuid": "string",
                  "niddId": "string",
                  "distname": "string",
                  "parameterName": "complexParam",
                  "state": "new",
                  "parameter": {
                    "parameterType": "simple",
                    "simpleParameter": {
                      "name": "ntpServerIpAddrList",
                      "state": "unchanged",
                      "value": "10.192.33.0"
                    },
                    "simpleListParameter": {
                      "name": "ntpServerIpAddrList",
                      "state": "unchanged",
                      "value": [
                        "10.192.33.0",
                        "10.192.33.1"
                      ]
                    },
                    "complexParameter": {
                      "name": "ntpServerIpAddrList",
                      "state": "unchanged",
                      "value": [
                        {
                          "structureParameters": [
                            null
                          ]}]}}}]}

        """
        return self._cu.search_parameters_of_current_plan(parameter_name=parameter_name, **kwargs)

