    def get_active_alarms(self, timeout=None, **kwargs):
        """
        Gets the list of active alarms and total number of them.

        .. note::
            SUPPORTS INTERNAL AND M2M API

        :param Union[int,str,float] timeout: (optional) Timeout for the operation.
        :param bool paging: (optional) Paging fetch alarm flag.
                            If set to False, all alarms will be read by this keyword at once.
                            If set to True, only returning the alarms in the given active page_number and their amount is
                            determined by the parameter items_per_page.
                            Default value is False.
        :param int page_number: Active page number - mandatory when paging=False; defaults to None
        :param int items_per_page: The number of alarms per page - mandatory when paging=False; defaults to None
        :param str sorted_by: Sorting criteria. Available values: appearTime, clearedTime, severity, faultId, faultName,
                                                                  alarmId, alarmName, faultSource
                                                Default value: appearTime
        :param str sort_order: Sorting order. Available values : desc, asc. Default value : desc
        :param list[AlarmSeverity] filter_by_severity: Filtering severity values.
                                                       Available values : critical, major, minor, warning, indeterminate
        :param list[str] filter_by_alarming_object (optional): Filtering by alarming objects
        :param str filter_by_text: Case insensitive text filter that can be used to filter alarms by the following
                                   fields: faultId, faultName, alarmId, alarmName, alarmingObject and severity
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) m2m feature activation flag.
                             If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults set to True.
        :param bool raw: (optional) If set to True, the raw response will be returned.
                         Defaults to False.
        :return: dict including: total - the alarms amount
                                 alarms - alarms info list
                {
                  "total": 1,
                  "alarms": [
                    {
                      "uuid": "10",
                      "severity": "critical",
                      "alarmId": 7665,
                      "alarmName": "BASE STATION TRANSMISSION ALARM",
                      "faultId": "2016",
                      "faultName": "BB bus reception error (summing device)",
                      "alarmingObject": "MRBTS-123/NRBTS-123/NRCEL-1111",
                      "appearTime": "1578899666704",
                      "lastUpdatedTime": "1578899666704",
                      "affectedCells": {
                        "faultyCells": [
                          "NRCELL-1",
                          "NRCELL-2"
                        ],
                        "degradedCells": []
                      },
                      "probableCauseName": "File error",
                      "additionalInfo": "Failed IP: 192.192.234.210",
                      "eventTypeName": "Processing error"
                    }
                  ],
                  "btsName": "VCU_3430",
                  "btsId": 3430,
                  "time": "2023-01-04T17:09:27+08:00"
                }
        """
        return self._cu.get_active_alarms(timeout=timeout, **kwargs)

