    def update_parameters_of_delta_plan(self, plan_id, mo_uuid, parameter_change_list):
        """
        Update parameters in a managed object

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str plan_id: Identifier of the plan.
        :param str mo_uuid: mo_uuid
        :param list parameter_change_list: list of dicts containing parameter change data:
            :param str operation_type: Type of operation on the provided parameter in path
                                       [add, replace, remove, revert]
            :param str parameter_path: Path of specific parameter
            :param str value: (optional) Detail value of parameter in path
            Example:
                parameter_change_list = [{"operation_type":"add", "parameter_path":"/lssConfig/lssPortNo",
                                             "value":"some_value"}]

                if add structure parameter and root parameter didn't exist, parameter_change_list should be like:
                parameter_change_list = [
                {"operation_type":"add", "parameter_path":"/nrPlanDNList"},
                {"operation_type":"add", "parameter_path":"/nrPlanDNList/0"},
                {"operation_type":"add", "parameter_path":"/nrPlanDNList/0/parameter_name", "value":"some_value"}]

                if add structure parameter and already exist a son parameter, parameter_change_list should be like:
                parameter_change_list = [
                {"operation_type":"add", "parameter_path":"/nrPlanDNList/1"},
                {"operation_type":"add", "parameter_path":"/nrPlanDNList/1/parameter_name", "value":"some_value"}]

        :return: It returns dict containing information about action_id, status and error_message
        """
        return self._cu.update_parameters_of_delta_plan(plan_id, mo_uuid, parameter_change_list)

