    def get_counter(self, measurement_id, dimension_dist_name, counter_id, timeout=30, **kwargs):
        """
        Retrieves counter value from a measurement

        :param measurement_id: (cuoam_19b only) Measurement id
        :param dimension_dist_name: Aggregation dimension distName of the measurement you want to retrive, for example,
                                    LNCEL-2%/FEARFCN-5035
        :param counter_id: Counter id
        :param Union[int,str] timeout: (optional) Timeout for the operation. Defaults to 30.
        :param str start_time_lower_limit: (cuoam_21b only, optional) interval start time coded in percent-encoded
            ISO 8601 format, for example: 2021-03-17T08:11:44+01:00
        :param str start_time_upper_limit: (cuoam_21b only, optional) interval end time coded in percent-encoded
            ISO 8601 format, for example: 2021-03-17T08:11:44+01:00
        :param bool raw: (optional) If set to True, the raw response will be returned. Defaults to False.
        :return: (for cuoam_19b): It returns dict with counter information: id, dimension_disname, measurement_id and values.
        Example (cuoam_19b):
        {
            "id": "M55110C1",
            "dimensionDistName": "LNCEL-2/EARFCN-5035",
            "measurementId": "55110",
            "values": [
                {
                    "startTime": "2019-05-07T12:15:00+03:00",
                  "value": "26604"
                }
            ]
        }
        Example (cuoam_21b), counter exists:
        {
            "id": "M55110C1",
            "dimensionDistName": "LNCEL-2/EARFCN-5035",
            "measurementId": None,
            "values": [
                {
                    "startTime": "2019-05-07T12:15:00+03:00",
                    "value": "26604"
                }
            ]
        }
        """
        return self._cu.get_counter(measurement_id, dimension_dist_name=dimension_dist_name,
                                    counter_id=counter_id, timeout=timeout, **kwargs)

    def get_counter_info(self, counter_id, measurement_id=None):
        """
        Retrieves additional information for a counter inside a measurement

        :param counter_id: Counter id
        :param measurement_id: (mandatory only for releases older than 26R1) Measurement id
        :return: It returns schema object CounterInfoPMV1 with counter information: id, name, abbreviation, description and unit.
        Example:
        {
            "id": "M8034C0",
            "name": "Number of A4 measurement activations for Measurement Based IMLB",
            "abbreviation": "A4_MEAS_ACT_MBIMLB",
            "description": "This measurement represents the number of times the eNB activates A4 measurements for Idle
            Mode Load Balancing (IMLB) in the UE. The counter is updated in the LTE cell, where A4 IMLB activation is
            sent by the eNB (with separate counters for each E-UTRA carrier frequency for which A4 measurements is
            activated).",
            "unit": "Integer number"
        }
        """
        return self._cu.get_counter_info(counter_id=counter_id, measurement_id=measurement_id)

