    def update_local_user_account(self, username, password="", new_username="", new_password="", active_status=""):
        """
        Update local account username and password

        .. note::
            After changing username and/or password user is automatically logged out and must reconnect using new credentials

        .. note::
            **API used:**

            PATCH /api/asm/v1/account/users/system

        :param str username: current username, different usernames can be used to distinguish different user roles,
                             and username is fixed.
                             For BTS Security Administrator use BTSSecurity
                             For BTS Application Administrator use BTSApplication
                             For BTS Read-Only User use BTSRead
        :param str password: (optional) current password
        :param str new_username: (optional) new desired username
        :param str new_password: (optional) new desired password
        :param str active_status: (optional) user status can be one of "active" or "deactive"

        :raises: ValueError: if active_status is not one of "active" or "deactive"

        :return: information about success or failure, for example:

            .. code-block:: python

                {
                  "summary": "Update local user account",
                  "content": "Success"
                }
        """
        if active_status and active_status.lower() not in ["active", "deactive"]:
            raise ValueError(f"active_status parameter value must be one of 'active' or 'deactive' not {active_status}")

        return self._cu.update_local_user_account(username=username,
                                                  password=password,
                                                  new_username=new_username,
                                                  new_password=new_password,
                                                  active_status=active_status.lower() if active_status else "")

