    @deprecated(substitute="perform_delta_recommissioning")
    def provision_vcu_delta_plan(self, mo_info_list, timeout=30, use_m2m=True):
        """
        Use of this keyword is deprecated - please use perform_delta_recommissioning instead.

        Provision Vcu Delta Plan - responsible for both validation and activation of delta plan.
                                   Activation will be performed asynchronously.
                                   In order to ensure successful activation, it is recommended to check the status
                                   of the operation using get_provision_vdu_delta_plan_status.

                                   For more information, refer to the delta-commissioning-example.md file.

        .. note::
            SUPPORTS M2M AND INTERNAL API

        :param list mo_info_list: list of dicts consisting of "class_name", "dist_name", "operation_type", "payload"
                                    - operation_type supports: 'create', 'update', 'delete'
                                    - payload needs to be a valid JSON string!
                                  for example:
                                    [
                                        {
                                            'class_name': 'QOS',
                                            'dist_name': 'MRBTS-10782/TNLSVC-1/TNL-1/IPNO-1/QOS-1',
                                            'operation_type': 'update',
                                            'payload': "{\"arpPcp\": 6}"
                                        },

                                        {
                                            'class_name': 'QOS',
                                            'dist_name': 'MRBTS-10782/TNLSVC-1/TNL-1/IPNO-1/QOS-2',
                                            'operation_type': 'create',
                                            'payload': "{\"arpPcp\": 6}"
                                        }
                                    ]
        :param int timeout: (optional) Timeout for the operation.
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) m2m feature activation flag.
                     If set to False, internal API will be used instead of licensed API (M2M).
                     Defaults to True.
        :return: M2mOperationResponseV1 object
        """
        self._validate_mo_info_list(mo_info_list)
        return self._cu.provision_vcu_delta_plan(mo_info_list=mo_info_list, timeout=timeout, use_m2m=use_m2m)

    @staticmethod
    def _validate_mo_info_list(mo_info_list):
        """
        Validate mo_info_list used in provision_vdu_delta_plan
        """
        mandatory_elements = {"class_name", "dist_name", "operation_type", "payload"}
        available_operations = {"create", "update", "delete"}

        for i, mo_info in enumerate(mo_info_list):
            if not mandatory_elements.issubset(mo_info.keys()):
                missing_elements = mandatory_elements - set(mo_info.keys())
                raise ValueError(
                    f"Dictionary at index {i} is missing the following elements: {', '.join(missing_elements)}")

            if mo_info["operation_type"] not in available_operations:
                raise ValueError(f"Operation '{mo_info['operation_type']}' not in {available_operations}")

            try:
                json.loads(mo_info['payload'])
            except ValueError:
                raise ValueError(f"Invalid JSON payload in mo_info_list at index {i}")

