    def update_rad_debug_params(self, persistency=None, domain_name=None, parameters=None, node_id=None, timeout=30,
                                **kwargs):
        """
        Keyword to Trigger Update R&D Debug Param

        .. note::
            SUPPORTS INTERNAL AND M2M API

        :param str persistency: should be persistent, notPersistent or oneReset.
        - persistent means persistent over all BTS resets.
        - notPersistent means not persistent change.
        - oneReset means persistent change over only one BTS reset. Not providing persistency means persistent.
        - default value is None means Restore all Non-default R&D Debug Parameter
        :param str domain_name: Specify target domain name to update params in it.
        :param list parameters: Params to be updated. Not providing any param means 'all params' (in the domain if domain is specified).
         parameters cannot be provided without domainName
        :param int node_id: node id, default is None means 'all node'
        :param int timeout: (optional) Timeout for the operation, defaults to 30
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) m2m feature activation flag.
                             If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :return: a object of RadDebugParamUpdateResponse
        """
        if persistency and persistency not in ["persistent", "notPersistent", "oneReset"]:
            raise ValueError(f"Incorrect value of 'persistency'. Should be one of: "
                             f"['persistent', 'notPersistent', 'oneReset'], your value: `{persistency}`")

        return self._cu.update_rad_debug_params(persistency=persistency,
                                                node_id=node_id,
                                                domain_name=domain_name,
                                                parameters=parameters,
                                                timeout=timeout,
                                                **kwargs)

